import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("a single sword → base premium 100 G + 10 G first insurance + 5 G fee = 115 G");
    it.todo("a single amulet → base premium 60 G + 6 G first insurance + 5 G fee = 71 G");
    it.todo("a single staff → base premium 80 G + 8 G first insurance + 5 G fee = 93 G");
    it.todo("a single potion → base premium 40 G + 4 G first insurance + 5 G fee = 49 G");
    it.todo("a single rune → base premium 25 G + 2.5 G first insurance + 5 G fee = 33 G (rounded up)");
    it.todo("a single moonstone → base premium 25 G + 2.5 G first insurance + 5 G fee = 33 G (rounded up)");
  });

  describe("quote — building block of 3 alike components", () => {
    it.todo("2 runes → 50 G base premium");
    it.todo("3 runes → 60 G base premium (block applies)");
    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
    it.todo("7 runes → 175 G base premium");
  });

  describe("quote — 'alike' components means same type", () => {
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
  });

  describe("quote — item-specific modifiers", () => {
    it.todo("cursed sword adds a 50 % surcharge on the item's base premium → 150 G base");
    it.todo("sword with enchantment 5 → high-enchantment surcharge applies (130 G base)");
    it.todo("sword with enchantment 4 → no high-enchantment surcharge (100 G base)");
    it.todo("cursed sword with enchantment 5 → both surcharges apply (180 G base)");
  });

  describe("quote — modifier scope on multi-item policies", () => {
    it.todo("cursed sword + plain amulet → curse adds 50 G (50 % of the sword only), 210 G before further modifiers and fee");
  });

  describe("quote — policy-wide modifiers", () => {
    it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
    it.todo("customer with 1 year with MHPCO → no loyalty discount");
    it.todo("a first insurance carries a 10 % initial assessment surcharge on the policy base premium");
    it.todo("each contract after the customer's first gets a 15 % discount");
    it.todo("a 5 G processing fee is added to every premium");
  });

  describe("quote — rounding in the MHPCO's favor", () => {
    it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
  });

  describe("quote — integration examples", () => {
    it.todo("newcomer (0 years, no previous contract) with a cursed steel sword enchantment 3 → premium 165 G");
    it.todo("long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G");
  });

  describe("quote — errors", () => {
    it.todo("an item with an unknown type (e.g. broomstick) → error");
  });

  describe("claim — standard reimbursement", () => {
    it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
    it.todo("damage to a rune (insurance value 250 G), damage 200 G → payout 100 G");
  });

  describe("claim — special clauses", () => {
    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (dragon: full, then deductible)");
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
    it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
  });

  describe("claim — deductible per damage event", () => {
    it.todo("a dragon attack damages a sword (500 G) and an amulet (300 G) → payout 600 G (deductible once per damaged item)");
  });

  describe("claim — insurance sum and cap", () => {
    it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
    it.todo("a cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
    it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G, cap 3500 G (block discount affects the premium only)");
    it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
  });

  describe("claim — cap exhaustion across successive claims", () => {
    it.todo("sword (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
    it.todo("sword (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");
  });

  describe("claim — multiple items of the same type", () => {
    it.todo("two swords insured, both damaged → each damage entry gets its own deductible");
    it.todo("more damage entries of a type than the policy covers (two sword damages, one sword insured) → error");
  });

  describe("claim — rounding in the MHPCO's favor", () => {
    it.todo("a payout calculation that yields 350.5 G → final payout 350 G (rounded down)");
  });

  describe("claim — errors", () => {
    it.todo("a damage entry whose item is not part of the policy (amulet damaged, only a sword insured) → error");
    it.todo("a damage entry with an unknown item type → error");
    it.todo("a damage entry with amount -200 → error");
  });

  describe("scenario processing", () => {
    it.todo("results array has the same length and order as the input steps");
    it.todo("a claim step refers to the policy created by an earlier quote step via its zero-based step index");
  });
});

