export interface Scenario {
  customer: { yearsWithMHPCO: number };
  steps: Step[];
}

export type Step = QuoteStep | ClaimStep;

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export type Result = QuoteResult | ClaimResult;

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export interface ScenarioResult {
  results: Result[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 1 / 10;
// Base premium for a single item of each type.
const UNIT_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

// A building block of 3 alike components is offered at a special base premium.
const basePremiumForAlikeItems = (type: string, count: number): number =>
  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * UNIT_BASE_PREMIUMS[type];

const policyBasePremium = (items: Item[]): number =>
  [...countByType(items)].reduce(
    (total, [type, count]) => total + basePremiumForAlikeItems(type, count),
    0,
  );

// Premiums round up, in the MHPCO's favour. The surcharge is added as a
// separate term rather than folded into a `base * 1.1` factor, which is not
// exact in binary floating point (100 * 1.1 === 110.00000000000001).
const quotePremium = (items: Item[]): number => {
  const base = policyBasePremium(items);
  return Math.ceil(base + base * FIRST_INSURANCE_SURCHARGE_RATE + PROCESSING_FEE);
};

const quote = (step: QuoteStep): QuoteResult => ({
  premium: quotePremium(step.items),
});

const runStep = (step: Step): Result => {
  switch (step.op) {
    case "quote":
      return quote(step);
    default:
      throw new Error(`unsupported step: ${step.op}`);
  }
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map(runStep),
});

