export interface Customer {
  yearsWithMHPCO: number;
}

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export type Step = QuoteStep | ClaimStep;

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export interface Item {
  type: string;
  material?: string;
  enchantment?: number;
  cursed?: boolean;
}

export interface ClaimStep {
  op: "claim";
  policy: number;
  incident: Incident;
}

export interface Incident {
  cause: string;
  damages: Damage[];
}

export interface Damage {
  itemType: string;
  amount: number;
}

export type Result = QuoteResult | ClaimResult;

export interface QuoteResult {
  premium: number;
}

export interface ClaimResult {
  payout: number;
  remainingCap: number;
}

export interface ScenarioResult {
  results: Result[];
}

const PROCESSING_FEE = 5;
const FIRST_INSURANCE_SURCHARGE_RATE = 1 / 10;
// Base premium for a single item of each type.
const UNIT_BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const LOYALTY_YEARS_THRESHOLD = 2;
const LOYALTY_DISCOUNT_RATE = 2 / 10;
const CURSE_SURCHARGE_RATE = 1 / 2;
const HIGH_ENCHANTMENT_THRESHOLD = 5;
const HIGH_ENCHANTMENT_SURCHARGE_RATE = 3 / 10;
const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const unitBasePremium = (type: string): number => UNIT_BASE_PREMIUMS[type];

const countByType = (items: Item[]): Map<string, number> =>
  items.reduce(
    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
    new Map<string, number>(),
  );

// A building block of 3 alike components is offered at a special base premium.
const basePremiumForItemGroup = (type: string, count: number): number =>
  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * unitBasePremium(type);

const policyBasePremium = (items: Item[]): number =>
  [...countByType(items)].reduce(
    (total, [type, count]) => total + basePremiumForItemGroup(type, count),
    0,
  );

const isHighlyEnchanted = (item: Item): boolean =>
  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;

const surchargeRate = (item: Item): number =>
  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);

// Item-specific modifiers apply to the affected item's own base premium, i.e.
// the unit price of its type — a block discount never shrinks a surcharge.
const itemSurcharge = (item: Item): number =>
  unitBasePremium(item.type) * surchargeRate(item);

const itemSurcharges = (items: Item[]): number =>
  items.reduce((total, item) => total + itemSurcharge(item), 0);

const isLongStanding = (customer: Customer): boolean =>
  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD;

// Policy-wide modifiers apply to the policy base premium only — never to the
// item surcharges. Net signed delta: a discount can outweigh the surcharge.
const policyAdjustmentRate = (customer: Customer): number =>
  FIRST_INSURANCE_SURCHARGE_RATE -
  (isLongStanding(customer) ? LOYALTY_DISCOUNT_RATE : 0);

// Premiums round up, in the MHPCO's favour. The adjustment is added as a
// separate term rather than folded into a `base * 1.1` factor, which is not
// exact in binary floating point (100 * 1.1 === 110.00000000000001).
const quotePremium = (items: Item[], customer: Customer): number => {
  const base = policyBasePremium(items);
  return Math.ceil(
    base +
      itemSurcharges(items) +
      base * policyAdjustmentRate(customer) +
      PROCESSING_FEE,
  );
};

const quote = (step: QuoteStep, customer: Customer): QuoteResult => ({
  premium: quotePremium(step.items, customer),
});

const runStep = (step: Step, customer: Customer): Result => {
  switch (step.op) {
    case "quote":
      return quote(step, customer);
    default:
      throw new Error(`unsupported step: ${step.op}`);
  }
};

export const runScenario = (scenario: Scenario): ScenarioResult => ({
  results: scenario.steps.map((step) => runStep(step, scenario.customer)),
});

