  result: {
    premium: quotePremium(step.items, state.customer, state.contractsSoFar > 0),
  },
  state: withPolicy(
    { ...state, contractsSoFar: state.contractsSoFar + 1 },
    stepIndex,
    openPolicy(step.items),
  ),
});

// A deductible applies per damage event, i.e. once per damaged item.
const damagePayout = (damage: Damage): number => damage.amount - DEDUCTIBLE;

const claim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
  const policy = state.policies.get(step.policy)!;
  const payout = step.incident.damages.reduce(
    (total, damage) => total + damagePayout(damage),
    0,
  );
  const remainingCap = policy.remainingCap - payout;
  return {
    result: { payout, remainingCap },
    state: withPolicy(state, step.policy, { ...policy, remainingCap }),
  };
};

const runStep = (
  step: Step,
  state: ScenarioState,
  stepIndex: number,
): StepOutcome => {
  switch (step.op) {
    case "quote":
      return quote(step, state, stepIndex);
    case "claim":
      return claim(step, state);
