// What a single damage entry entitles the claimant to, before the policy-wide
// cap is applied. A deductible applies per damage event, i.e. once per damaged
// item. Special clauses reduce the reimbursement first; the deductible comes
// off after.
const damageEntitlement = (damage: Damage, item: Item): number =>
  damage.amount * reimbursementRate(item) - DEDUCTIBLE;

// The insured item a damage entry refers to. Matching is by type alone, so
// with several alike items insured this picks the first; that only becomes
// observable once multiple items of one type are supported.
const damagedItem = (policy: Policy, damage: Damage): Item =>
  policy.items.find((item) => item.type === damage.itemType)!;

const claim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
  const policy = state.policies.get(step.policy)!;
  const desiredPayout = step.incident.damages.reduce(
    (total, damage) =>
      total + damageEntitlement(damage, damagedItem(policy, damage)),
    0,
  );
  // The total payout per policy is capped; a claim gets at most what is left.
  const payout = Math.min(desiredPayout, policy.remainingCap);
  const remainingCap = policy.remainingCap - payout;
  return {
    result: { payout, remainingCap },
    state: withPolicy(state, step.policy, { ...policy, remainingCap }),
  };
};

