// Pairs each damage entry with a distinct insured item of the same type: two
// damages to "sword" refer to two different insured swords, not the same one
// twice. Instances of a type are consumed in the order they were insured.
const matchDamagesToItems = (policy: Policy, damages: Damage[]): Item[] => {
  const unclaimed = [...policy.items];
  return damages.map((damage) => {
    const index = unclaimed.findIndex((item) => item.type === damage.itemType);
    return unclaimed.splice(index, 1)[0];
  });
};

const claim = (step: ClaimStep, state: ScenarioState): StepOutcome => {
  const policy = state.policies.get(step.policy)!;
  const { damages } = step.incident;
  const damagedItems = matchDamagesToItems(policy, damages);
  const desiredPayout = damages.reduce(
    (total, damage, index) =>
      total + damageEntitlement(damage, damagedItems[index]),
    0,
  );

