// Payouts round down, in the MHPCO's favour. Rounding happens before the cap
// is applied so that `remainingCap` is derived from the amount actually paid.
const payout = Math.min(Math.floor(entitlement), remainingCap);
return { payout, remainingCap: remainingCap - payout };

