// A rejected scenario produces an error description on stderr and a non-zero
// exit status — never a partial `results` document on stdout.
const main = async (): Promise<void> => {
  try {
    process.stdout.write(JSON.stringify(runScenario(await readScenario())));
  } catch (error) {
    process.stderr.write(`${(error as Error).message}\n`);
    process.exitCode = 1;
  }
};

await main();

